{
  // ──────────────────────────────────────────────────────────────────────────
  // Dev Container — MLOps Playbook
  // ──────────────────────────────────────────────────────────────────────────
  //
  // WHAT IS A DEV CONTAINER?
  //   A Dev Container is a Docker-based development environment defined as code.
  //   When you open this repo in VS Code (or GitHub Codespaces), it automatically
  //   builds a container with all tools pre-installed: Python, DVC, MLflow,
  //   Terraform, kubectl, the GitHub CLI, and Docker-in-Docker.
  //
  //   This means every team member gets an identical environment — no more
  //   "works on my machine" problems.
  //
  // HOW TO USE:
  //   1. Install the "Dev Containers" VS Code extension.
  //   2. Open the command palette → "Dev Containers: Reopen in Container".
  //   3. Wait for the container to build (~3 minutes on first run).
  //   4. Run `task setup:dev` to install Python dev dependencies.
  //
  // PORTS FORWARDED:
  //   5000  — MLflow UI
  //   9000  — MinIO S3 API
  //   9001  — MinIO Console
  //   8000  — Triton / vLLM inference
  //   8080  — TorchServe inference
  //   5432  — PostgreSQL (for direct DB inspection)

  "name": "MLOps Playbook",

  // Python 3.11 base image — matches production Python version.
  "image": "mcr.microsoft.com/devcontainers/python:3.11",

  // ──────────────────────────────────────────────────────────────────────────
  // GPU passthrough — RTX 5070 (Blackwell, SM_120, 12 GB GDDR7)
  // --gpus all passes all host NVIDIA GPUs into the container via the NVIDIA
  // Container Toolkit (bundled with Docker Desktop for Windows ≥ 4.28).
  // Prerequisites: NVIDIA driver ≥ 572.x, CUDA 12.8+, WSL 2, Docker Desktop.
  // See: docs/local-setup.md § Part 1 for full host setup instructions.
  // ──────────────────────────────────────────────────────────────────────────
  "runArgs": ["--gpus", "all"],

  // GPU requirement declaration — Codespaces will request a GPU instance.
  "hostRequirements": {
    "gpu": "optional"
  },

  // ──────────────────────────────────────────────────────────────────────────
  // Dev Container Features
  // Features are modular add-ons that layer tooling onto the base image.
  // ──────────────────────────────────────────────────────────────────────────
  "features": {
    // Docker-in-Docker: lets you run `docker compose` from inside the container.
    // Required to start the MLflow stack (PostgreSQL + MinIO + MLflow).
    "ghcr.io/devcontainers/features/docker-in-docker:2": {
      "version": "latest",
      "dockerDashComposeVersion": "v2"
    },

    // Terraform CLI — for editing and validating IaC in terraform/.
    "ghcr.io/devcontainers/features/terraform:1": {
      "version": "1.8"
    },

    // kubectl — for interacting with Kubernetes clusters (serving deployments).
    "ghcr.io/devcontainers/features/kubectl-helm-minikube:1": {
      "version": "latest",
      "helm": "latest",
      "minikube": "none"
    },

    // GitHub CLI — for creating PRs, checking workflow runs, managing releases.
    "ghcr.io/devcontainers/features/github-cli:1": {
      "version": "latest"
    },

    // AWS CLI — for DVC remote (S3) and SageMaker Terraform.
    "ghcr.io/devcontainers/features/aws-cli:1": {
      "version": "latest"
    },

    // Google Cloud CLI — for DVC remote (GCS) and Vertex AI Terraform.
    "ghcr.io/devcontainers/features/gcloud-cli:1": {
      "version": "latest"
    },

    // Azure CLI — for Azure ML Terraform and azure-ml CI jobs.
    "ghcr.io/devcontainers/features/azure-cli:1": {
      "version": "latest"
    },

    // Node.js (LTS) — required by some pre-commit hooks and markdownlint.
    "ghcr.io/devcontainers/features/node:1": {
      "version": "lts"
    }
  },

  // ──────────────────────────────────────────────────────────────────────────
  // Post-create command — runs once after the container is built.
  // ──────────────────────────────────────────────────────────────────────────
  "postCreateCommand": {
    // Install Taskfile (cross-platform task runner — alternative to Make).
    "install-task": "sh -c \"$(curl --location https://taskfile.dev/install.sh)\" -- -d -b /usr/local/bin",

    // Install core ML + dev Python dependencies.
    "pip-install": "pip install --upgrade pip && pip install mlflow==2.14.2 'dvc[s3,gcs,azure]>=3.0' 'evidently>=0.4' pandas scikit-learn pyarrow 'fairlearn>=0.10' 'shap>=0.44' 'matplotlib>=3.8' feast 'pyyaml>=6.0' 'requests>=2.31' pre-commit black isort ruff bandit detect-secrets pip-audit pytest pytest-cov",

    // Install pre-commit hooks so they run on every commit inside the container.
    "pre-commit-install": "pre-commit install && pre-commit install --hook-type commit-msg",

    // Install markdownlint (used by pre-commit markdownlint hook).
    "markdownlint": "npm install -g markdownlint-cli",

    // Install actionlint (GitHub Actions workflow linter).
    "actionlint": "curl -L https://github.com/rhysd/actionlint/releases/latest/download/actionlint_linux_amd64.tar.gz | tar xz -C /usr/local/bin"
  },

  // ──────────────────────────────────────────────────────────────────────────
  // VS Code settings applied inside the container.
  // ──────────────────────────────────────────────────────────────────────────
  "customizations": {
    "vscode": {
      "settings": {
        // Use Black as the Python formatter.
        "python.defaultInterpreterPath": "/usr/local/bin/python",
        "[python]": {
          "editor.defaultFormatter": "ms-python.black-formatter",
          "editor.formatOnSave": true,
          "editor.codeActionsOnSave": {
            "source.organizeImports": "explicit"
          }
        },
        // Show Terraform formatting on save.
        "[terraform]": {
          "editor.defaultFormatter": "hashicorp.terraform",
          "editor.formatOnSave": true
        },
        // Trim trailing whitespace on every save.
        "files.trimTrailingWhitespace": true,
        "files.insertFinalNewline": true,
        // DVC file associations — treat .dvc files as YAML.
        "files.associations": {
          "*.dvc": "yaml",
          "dvc.lock": "yaml",
          "Taskfile.yml": "yaml"
        }
      },
      "extensions": [
        // Python
        "ms-python.python",
        "ms-python.pylance",
        "ms-python.black-formatter",
        "ms-python.isort",
        "charliermarsh.ruff",
        // Notebooks (for exploratory analysis)
        "ms-toolsai.jupyter",
        // Terraform / IaC
        "hashicorp.terraform",
        // Docker & Kubernetes
        "ms-azuretools.vscode-docker",
        "ms-kubernetes-tools.vscode-kubernetes-tools",
        // GitHub Actions
        "github.vscode-github-actions",
        // YAML (DVC pipeline files, GitHub Actions)
        "redhat.vscode-yaml",
        // Markdown
        "yzhang.markdown-all-in-one",
        // Git
        "mhutchie.git-graph",
        "eamodio.gitlens",
        // Environment variable files
        "irongeek.vscode-env"
      ]
    }
  },

  // ──────────────────────────────────────────────────────────────────────────
  // Port forwarding — these ports will be accessible on localhost.
  // ──────────────────────────────────────────────────────────────────────────
  "forwardPorts": [5000, 9000, 9001, 8000, 8080, 8001, 5432],
  "portsAttributes": {
    "5000": { "label": "MLflow UI",            "onAutoForward": "notify" },
    "9001": { "label": "MinIO Console",         "onAutoForward": "notify" },
    "9000": { "label": "MinIO S3 API",          "onAutoForward": "silent" },
    "8000": { "label": "Triton / vLLM",         "onAutoForward": "silent" },
    "8080": { "label": "TorchServe",            "onAutoForward": "silent" },
    "8001": { "label": "Triton gRPC",           "onAutoForward": "silent" },
    "5432": { "label": "PostgreSQL",            "onAutoForward": "silent" }
  },

  // Run the container as non-root (vscode user) for security.
  "remoteUser": "vscode"
}

"""
Purpose:
    Per-cloud health probe implementations for multi-cloud serving.
    Polls each cloud's native health endpoint every 30 seconds and records
    availability for use by the traffic router.

Usage:
    checker = HealthChecker(registry)
    status = checker.check_all()

Dependencies:
    requests>=2.31
    google-auth>=2.20 (GCP probe)
    azure-identity>=1.15 (Azure probe)
"""

from __future__ import annotations

import logging
import sys
from dataclasses import dataclass, field
from typing import Any

try:
    import requests
except ImportError as exc:
    print(f"ERROR: {exc}\nInstall with: pip install requests", file=sys.stderr)
    sys.exit(1)

logger = logging.getLogger(__name__)

_REQUEST_TIMEOUT = 10  # seconds


@dataclass
class HealthStatus:
    cloud: str
    model_name: str
    url: str
    is_healthy: bool
    status_code: int | None = None
    error: str | None = None
    latency_ms: float | None = None


class HealthChecker:
    """Runs health probes against all registered endpoints."""

    def __init__(self, registry: Any) -> None:
        self._registry = registry

    def check_all(self) -> list[HealthStatus]:
        results = []
        for model_name in self._registry.all_models():
            for ep in self._registry.list_endpoints(model_name):
                status = self._probe(
                    cloud=ep["cloud"],
                    model_name=model_name,
                    endpoint=ep,
                )
                results.append(status)
        return results

    def _probe(self, cloud: str, model_name: str, endpoint: dict[str, Any]) -> HealthStatus:
        url = endpoint.get("url", "")
        probe_fn = {
            "aws": self._probe_sagemaker,
            "gcp": self._probe_vertex,
            "azure": self._probe_azure,
        }.get(cloud, self._probe_generic)

        return probe_fn(cloud=cloud, model_name=model_name, url=url)

    def _probe_sagemaker(self, cloud: str, model_name: str, url: str) -> HealthStatus:
        """SageMaker: GET /ping returns 200 when endpoint is healthy."""
        import time

        ping_url = url.rstrip("/") + "/ping"
        start = time.monotonic()
        try:
            resp = requests.get(ping_url, timeout=_REQUEST_TIMEOUT)
            latency_ms = (time.monotonic() - start) * 1000
            return HealthStatus(
                cloud=cloud,
                model_name=model_name,
                url=url,
                is_healthy=resp.status_code == 200,
                status_code=resp.status_code,
                latency_ms=round(latency_ms, 2),
            )
        except requests.RequestException as exc:
            return HealthStatus(
                cloud=cloud, model_name=model_name, url=url,
                is_healthy=False, error=str(exc),
            )

    def _probe_vertex(self, cloud: str, model_name: str, url: str) -> HealthStatus:
        """
        Vertex AI: Query endpoint metadata via GCP REST API.
        Expects GOOGLE_APPLICATION_CREDENTIALS or ADC to be configured.
        """
        import time

        try:
            import google.auth
            import google.auth.transport.requests

            credentials, _ = google.auth.default(
                scopes=["https://www.googleapis.com/auth/cloud-platform"]
            )
            auth_req = google.auth.transport.requests.Request()
            credentials.refresh(auth_req)
            headers = {"Authorization": f"Bearer {credentials.token}"}
            start = time.monotonic()
            resp = requests.get(url, headers=headers, timeout=_REQUEST_TIMEOUT)
            latency_ms = (time.monotonic() - start) * 1000
            return HealthStatus(
                cloud=cloud, model_name=model_name, url=url,
                is_healthy=resp.status_code == 200,
                status_code=resp.status_code,
                latency_ms=round(latency_ms, 2),
            )
        except ImportError:
            return HealthStatus(
                cloud=cloud, model_name=model_name, url=url,
                is_healthy=False,
                error="google-auth not installed; run: pip install google-auth",
            )
        except Exception as exc:
            return HealthStatus(
                cloud=cloud, model_name=model_name, url=url,
                is_healthy=False, error=str(exc),
            )

    def _probe_azure(self, cloud: str, model_name: str, url: str) -> HealthStatus:
        """
        Azure ML Managed Online Endpoint: POST /score with empty body.
        Expects AZURE_CLIENT_ID/TENANT_ID/CLIENT_SECRET or Managed Identity.
        """
        import time

        try:
            from azure.identity import DefaultAzureCredential

            credential = DefaultAzureCredential()
            token = credential.get_token("https://ml.azure.com/.default").token
            headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
            start = time.monotonic()
            resp = requests.post(url, headers=headers, json={}, timeout=_REQUEST_TIMEOUT)
            latency_ms = (time.monotonic() - start) * 1000
            # Azure returns 400 (bad input) not 200 for health — both indicate endpoint is up
            is_healthy = resp.status_code in (200, 400)
            return HealthStatus(
                cloud=cloud, model_name=model_name, url=url,
                is_healthy=is_healthy,
                status_code=resp.status_code,
                latency_ms=round(latency_ms, 2),
            )
        except ImportError:
            return HealthStatus(
                cloud=cloud, model_name=model_name, url=url,
                is_healthy=False,
                error="azure-identity not installed; run: pip install azure-identity",
            )
        except Exception as exc:
            return HealthStatus(
                cloud=cloud, model_name=model_name, url=url,
                is_healthy=False, error=str(exc),
            )

    def _probe_generic(self, cloud: str, model_name: str, url: str) -> HealthStatus:
        import time

        start = time.monotonic()
        try:
            resp = requests.get(url, timeout=_REQUEST_TIMEOUT)
            latency_ms = (time.monotonic() - start) * 1000
            return HealthStatus(
                cloud=cloud, model_name=model_name, url=url,
                is_healthy=resp.ok,
                status_code=resp.status_code,
                latency_ms=round(latency_ms, 2),
            )
        except requests.RequestException as exc:
            return HealthStatus(
                cloud=cloud, model_name=model_name, url=url,
                is_healthy=False, error=str(exc),
            )

"""
Purpose:
    Traffic weight routing and automatic failover logic for multi-cloud model serving.
    Routes prediction requests across AWS SageMaker, GCP Vertex AI, and Azure ML
    endpoints using configurable weights.  Automatically shifts traffic away from
    unhealthy endpoints when error rate exceeds the failover threshold.

Usage:
    router = MultiCloudRouter(model_name="my-model", config_dir="multi_cloud_serving/routing-config/")
    result = router.predict(payload)

Dependencies:
    requests>=2.31
    pyyaml>=6.0
    mlflow>=2.14
"""

from __future__ import annotations

import logging
import random
import sys
import time
from pathlib import Path
from typing import Any

try:
    import mlflow
    import requests
    import yaml
except ImportError as exc:
    print(
        f"ERROR: {exc}\nInstall with: pip install requests pyyaml mlflow",
        file=sys.stderr,
    )
    sys.exit(1)

logger = logging.getLogger(__name__)

_FAILOVER_ERROR_RATE_THRESHOLD = 0.05  # 5% triggers failover
_FAILOVER_WINDOW_SECONDS = 120         # 2-minute window
_HEALTH_CHECK_INTERVAL_SECONDS = 30


class EndpointStats:
    """Rolling error-rate tracker for a single endpoint."""

    def __init__(self, window_seconds: int = _FAILOVER_WINDOW_SECONDS) -> None:
        self._window = window_seconds
        self._requests: list[tuple[float, bool]] = []  # (timestamp, is_error)

    def record(self, is_error: bool) -> None:
        now = time.monotonic()
        self._requests.append((now, is_error))
        cutoff = now - self._window
        self._requests = [(t, e) for t, e in self._requests if t >= cutoff]

    @property
    def error_rate(self) -> float:
        if not self._requests:
            return 0.0
        errors = sum(1 for _, is_error in self._requests if is_error)
        return errors / len(self._requests)


class MultiCloudRouter:
    """Route predictions across cloud endpoints with automatic failover."""

    def __init__(
        self,
        model_name: str,
        config_dir: str | Path = "multi_cloud_serving/routing-config/",
        tracking_uri: str = "http://localhost:5000",
    ) -> None:
        self._model_name = model_name
        self._config = self._load_config(Path(config_dir), model_name)
        self._stats: dict[str, EndpointStats] = {
            cloud: EndpointStats()
            for cloud in self._config.get("endpoints", {})
        }
        mlflow.set_tracking_uri(tracking_uri)

    def _load_config(self, config_dir: Path, model_name: str) -> dict[str, Any]:
        config_file = config_dir / f"{model_name}.yaml"
        if not config_file.exists():
            raise FileNotFoundError(
                f"No routing config found at {config_file}. "
                f"Create it using the schema in {config_dir / '_config-schema.yaml'}"
            )
        with config_file.open() as fh:
            return yaml.safe_load(fh)

    def _healthy_weights(self) -> dict[str, float]:
        """Return per-cloud weights, zeroing out unhealthy endpoints."""
        weights = {}
        for cloud, spec in self._config.get("endpoints", {}).items():
            if self._stats[cloud].error_rate > _FAILOVER_ERROR_RATE_THRESHOLD:
                logger.warning(
                    "Endpoint %s/%s error_rate=%.2f%% — removing from pool",
                    self._model_name,
                    cloud,
                    self._stats[cloud].error_rate * 100,
                )
                weights[cloud] = 0.0
            else:
                weights[cloud] = float(spec.get("weight", 0))

        total = sum(weights.values())
        if total == 0:
            raise RuntimeError(
                f"All endpoints for {self._model_name} are unhealthy — cannot route traffic."
            )
        return {c: w / total for c, w in weights.items()}

    def _select_cloud(self) -> str:
        weights = self._healthy_weights()
        clouds = list(weights.keys())
        probabilities = [weights[c] for c in clouds]
        return random.choices(clouds, weights=probabilities, k=1)[0]

    def predict(self, payload: dict[str, Any]) -> dict[str, Any]:
        """Send a prediction request to the selected cloud endpoint."""
        cloud = self._select_cloud()
        endpoint_url = self._config["endpoints"][cloud]["url"]

        try:
            response = requests.post(
                endpoint_url,
                json=payload,
                timeout=self._config.get("timeout_seconds", 30),
                headers={"Content-Type": "application/json"},
            )
            response.raise_for_status()
            is_error = False
            result = response.json()
            result["_serving_cloud"] = cloud
            return result
        except (requests.RequestException, ValueError) as exc:
            is_error = True
            logger.error("Prediction error on %s/%s: %s", self._model_name, cloud, exc)
            self._handle_failover(cloud)
            raise
        finally:
            self._stats[cloud].record(is_error)

    def _handle_failover(self, failed_cloud: str) -> None:
        if self._stats[failed_cloud].error_rate > _FAILOVER_ERROR_RATE_THRESHOLD:
            logger.error(
                "CrossCloudFailoverTriggered: %s is unhealthy (error_rate=%.2f%%). "
                "Traffic shifted to remaining endpoints.",
                failed_cloud,
                self._stats[failed_cloud].error_rate * 100,
            )

    def health_summary(self) -> dict[str, dict[str, Any]]:
        return {
            cloud: {
                "error_rate_pct": round(self._stats[cloud].error_rate * 100, 2),
                "healthy": self._stats[cloud].error_rate <= _FAILOVER_ERROR_RATE_THRESHOLD,
            }
            for cloud in self._stats
        }

"""
Purpose:
    GCP Pub/Sub consumer for online learning mini-batches.
    Pulls messages from a Pub/Sub subscription and accumulates them into
    mini-batches of at least min_batch_size records before yielding.
    Acknowledges messages only after the batch is successfully yielded.

Usage:
    consumer = PubSubStreamConsumer(
        config={"project_id": "my-project", "subscription": "ml-feedback-sub"},
        min_batch_size=500,
    )
    for batch in consumer.batches():
        updater.apply(batch)

Dependencies:
    google-cloud-pubsub>=2.18
"""

from __future__ import annotations

import json
import logging
import sys
from typing import Any, Generator

try:
    from google.cloud import pubsub_v1
    from google.api_core.exceptions import GoogleAPIError
except ImportError as exc:
    print(
        f"ERROR: {exc}\nInstall with: pip install google-cloud-pubsub",
        file=sys.stderr,
    )
    sys.exit(1)

logger = logging.getLogger(__name__)

_MAX_MESSAGES_PER_PULL = 500


class PubSubStreamConsumer:
    """
    Pulls messages from a GCP Pub/Sub subscription.

    Parameters
    ----------
    config : dict
        Required keys: project_id, subscription.
    min_batch_size : int
        Minimum records per yielded batch (default 500).
    """

    def __init__(self, config: dict[str, Any], min_batch_size: int = 500) -> None:
        self._project_id = config["project_id"]
        self._subscription = config["subscription"]
        self._min_batch_size = min_batch_size
        self._client = pubsub_v1.SubscriberClient()
        self._subscription_path = self._client.subscription_path(
            self._project_id, self._subscription
        )
        logger.info(
            "PubSubStreamConsumer ready — subscription=%s",
            self._subscription_path,
        )

    def batches(self) -> Generator[list[dict[str, Any]], None, None]:
        """Pull from Pub/Sub and yield mini-batches, acking after each yield."""
        buffer: list[dict[str, Any]] = []
        ack_ids: list[str] = []
        try:
            while True:
                try:
                    response = self._client.pull(
                        request={
                            "subscription": self._subscription_path,
                            "max_messages": _MAX_MESSAGES_PER_PULL,
                        }
                    )
                except GoogleAPIError as exc:
                    logger.error("PubSub pull error: %s", exc)
                    break
                for msg in response.received_messages:
                    try:
                        buffer.append(json.loads(msg.message.data.decode("utf-8")))
                        ack_ids.append(msg.ack_id)
                    except (json.JSONDecodeError, UnicodeDecodeError):
                        logger.warning("Skipping un-parseable Pub/Sub message.")
                if len(buffer) >= self._min_batch_size:
                    yield buffer
                    # Ack only after successful yield
                    self._client.acknowledge(
                        request={
                            "subscription": self._subscription_path,
                            "ack_ids": ack_ids,
                        }
                    )
                    buffer = []
                    ack_ids = []
        finally:
            if buffer:
                yield buffer
                if ack_ids:
                    self._client.acknowledge(
                        request={
                            "subscription": self._subscription_path,
                            "ack_ids": ack_ids,
                        }
                    )

    def close(self) -> None:
        self._client.close()
        logger.info("PubSubStreamConsumer closed.")

"""
Purpose:
    FastAPI REST API routes for deployment status, logs, and health checks.
    Reads Kubernetes deployment state via k8s_client.py.
    Mutations (scale, rollout) are dispatched as GitHub Actions workflows.

Usage:
    from portal.backend.api.deployments import router
    app.include_router(router, prefix="/api/deployments")

Dependencies:
    fastapi>=0.111, kubernetes>=29.0
"""

from __future__ import annotations

from typing import Any

from fastapi import APIRouter, Depends, HTTPException, status

from portal.backend.k8s_client import PortalK8sClient
from portal.backend.github_client import GitHubActionsClient

router = APIRouter(tags=["deployments"])


def _k8s() -> PortalK8sClient:
    return PortalK8sClient()


def _github() -> GitHubActionsClient:
    return GitHubActionsClient()


@router.get("/", summary="List all model deployments across namespaces")
def list_deployments(k8s: PortalK8sClient = Depends(_k8s)) -> list[dict[str, Any]]:
    return k8s.list_model_deployments()


@router.get("/{model_name}/{environment}", summary="Get deployment status and health")
def get_deployment(
    model_name: str,
    environment: str,
    k8s: PortalK8sClient = Depends(_k8s),
) -> dict[str, Any]:
    deployment = k8s.get_deployment_status(model_name=model_name, environment=environment)
    if not deployment:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Deployment '{model_name}' in '{environment}' not found",
        )
    return deployment


@router.post("/{model_name}/{environment}/rollback", summary="Trigger rollback via GitHub Actions")
def rollback_deployment(
    model_name: str,
    environment: str,
    github_client: GitHubActionsClient = Depends(_github),
) -> dict[str, str]:
    """Dispatch rollback workflow. The portal never modifies Kubernetes directly."""
    run_id = github_client.trigger_workflow(
        workflow_id="rollback.yml",
        inputs={"model_name": model_name, "environment": environment},
    )
    return {"status": "dispatched", "workflow_run_id": run_id}

"""
Purpose:
    FastAPI REST API routes for ML model registration, listing, and promotion.
    Read-only for model metadata (reads MLflow registry); all mutations
    are dispatched as GitHub Actions workflow triggers via github_client.py.

Usage:
    from portal.backend.api.models import router
    app.include_router(router, prefix="/api/models")

Dependencies:
    fastapi>=0.111, mlflow>=2.14
"""

from __future__ import annotations

from typing import Any

from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel

from portal.backend.mlflow_client import PortalMLflowClient
from portal.backend.github_client import GitHubActionsClient

router = APIRouter(tags=["models"])


class PromoteRequest(BaseModel):
    model_name: str
    model_version: str
    target_environment: str  # dev | staging | production


def _mlflow() -> PortalMLflowClient:
    return PortalMLflowClient()


def _github() -> GitHubActionsClient:
    return GitHubActionsClient()


@router.get("/", summary="List all registered models")
def list_models(mlflow_client: PortalMLflowClient = Depends(_mlflow)) -> list[dict[str, Any]]:
    return mlflow_client.list_models()


@router.get("/{model_name}", summary="Get model details with versions and metrics")
def get_model(
    model_name: str,
    mlflow_client: PortalMLflowClient = Depends(_mlflow),
) -> dict[str, Any]:
    model = mlflow_client.get_model(model_name)
    if not model:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=f"Model '{model_name}' not found")
    return model


@router.post("/promote", summary="Trigger promotion workflow via GitHub Actions")
def promote_model(
    request: PromoteRequest,
    github_client: GitHubActionsClient = Depends(_github),
) -> dict[str, str]:
    """Dispatch a promotion workflow. The portal never modifies MLflow directly."""
    run_id = github_client.trigger_workflow(
        workflow_id="promote.yml",
        inputs={
            "model_name": request.model_name,
            "model_version": request.model_version,
            "target_environment": request.target_environment,
        },
    )
    return {"status": "dispatched", "workflow_run_id": run_id}

"""
Purpose:
    Kubernetes client wrapper for the self-service portal.
    Reads Deployment and Pod status from the cluster; never modifies resources.

Usage:
    client = PortalK8sClient()
    deployments = client.list_model_deployments()

Dependencies:
    kubernetes>=29.0
"""

from __future__ import annotations

import logging
import os
from typing import Any

logger = logging.getLogger(__name__)

_MODEL_NAMESPACES = ["mlops-dev", "mlops-staging", "mlops-production"]


class PortalK8sClient:
    """Read-only Kubernetes client for deployment status used by the portal."""

    def __init__(self) -> None:
        try:
            from kubernetes import client as k8s_client, config as k8s_config

            try:
                k8s_config.load_incluster_config()
            except Exception:
                k8s_config.load_kube_config()
            self._apps_v1 = k8s_client.AppsV1Api()
            self._core_v1 = k8s_client.CoreV1Api()
        except ImportError as exc:
            logger.warning("kubernetes SDK not installed: %s", exc)
            self._apps_v1 = None
            self._core_v1 = None

    def list_model_deployments(self) -> list[dict[str, Any]]:
        if not self._apps_v1:
            return []
        results = []
        for ns in _MODEL_NAMESPACES:
            try:
                deployments = self._apps_v1.list_namespaced_deployment(namespace=ns)
                for d in deployments.items:
                    labels = d.metadata.labels or {}
                    results.append(
                        {
                            "name": d.metadata.name,
                            "namespace": ns,
                            "model_name": labels.get("model-name", ""),
                            "replicas": d.spec.replicas,
                            "ready_replicas": d.status.ready_replicas or 0,
                        }
                    )
            except Exception as exc:
                logger.warning("Failed to list deployments in %s: %s", ns, exc)
        return results

    def get_deployment_status(
        self, model_name: str, environment: str
    ) -> dict[str, Any] | None:
        if not self._apps_v1:
            return None
        namespace = f"mlops-{environment}"
        try:
            deployments = self._apps_v1.list_namespaced_deployment(
                namespace=namespace,
                label_selector=f"model-name={model_name}",
            )
            if not deployments.items:
                return None
            d = deployments.items[0]
            return {
                "name": d.metadata.name,
                "namespace": namespace,
                "model_name": model_name,
                "environment": environment,
                "replicas": d.spec.replicas,
                "ready_replicas": d.status.ready_replicas or 0,
                "conditions": [
                    {"type": c.type, "status": c.status, "message": c.message}
                    for c in (d.status.conditions or [])
                ],
            }
        except Exception as exc:
            logger.warning("Failed to get deployment status: %s", exc)
            return None

