  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

resource "aws_s3_bucket" "ml_artifacts" {
  bucket = var.artifact_bucket_name
}

resource "aws_sagemaker_domain" "studio" {
  domain_name = var.sagemaker_domain_name
