# azure-ml/outputs.tf
#
# Exposes integration points for downstream consumers:
#   - GitHub Actions secrets (MLflow tracking URI, App Insights connection string)
#   - DVC remote configuration (storage account name + container)
#   - Serving deploy scripts (endpoint scoring URI, cluster names)
#   - Platform team cross-references (workspace ID, ACR login server)

# ---------------------------------------------------------------------------
# WORKSPACE
# ---------------------------------------------------------------------------

output "workspace_id" {
  description = "Azure ML Workspace resource ID. Used by `az ml` CLI commands and SDK v2 MLClient initialisation."
  value       = azurerm_machine_learning_workspace.ml.id
}

output "workspace_name" {
  description = "Azure ML Workspace name. Set as GitHub Actions secret AZURE_ML_WORKSPACE for CI job submissions."
  value       = azurerm_machine_learning_workspace.ml.name
}

output "workspace_resource_group" {
  description = "Resource group containing the workspace. Set as GitHub Actions secret AZURE_ML_RESOURCE_GROUP."
  value       = azurerm_resource_group.ml.name
}

output "mlflow_tracking_uri" {
  description = "AzureML MLflow tracking URI (azureml:// format). Set as GitHub Actions secret MLFLOW_TRACKING_URI. SDK v2 resolves this automatically when authenticated."
  value       = "azureml://eastus.api.azureml.ms/mlflow/v1.0/subscriptions/${data.azurerm_client_config.current.subscription_id}/resourceGroups/${azurerm_resource_group.ml.name}/providers/Microsoft.MachineLearningServices/workspaces/${azurerm_machine_learning_workspace.ml.name}"
}

output "workspace_discovery_url" {
  description = "Azure ML workspace discovery URL. Used by SDK v2 MLClient when authenticating non-interactively."
  value       = "https://ml.azure.com/workspaces/${azurerm_machine_learning_workspace.ml.id}"
}

output "workspace_principal_id" {
  description = "Object ID of the workspace system-assigned managed identity. Used to grant additional RBAC roles outside this module."
  value       = azurerm_machine_learning_workspace.ml.identity[0].principal_id
}

# ---------------------------------------------------------------------------
# STORAGE
# ---------------------------------------------------------------------------

output "storage_account_name" {
  description = "Storage account name. Required for DVC remote configuration and dataset registration."
  value       = azurerm_storage_account.ml.name
}

output "storage_account_id" {
  description = "Storage account resource ID. Used for additional role assignments from calling modules."
  value       = azurerm_storage_account.ml.id
}

output "artifacts_container_name" {
  description = "Blob container name for ML artefacts (model binaries, evaluation reports). Used in MLflow artifact store configuration."
  value       = azurerm_storage_container.ml_artifacts.name
}

output "dvc_remote_container_name" {
  description = "Blob container name for DVC dataset cache objects."
  value       = azurerm_storage_container.dvc_remote.name
}

output "dvc_remote_url" {
  description = "DVC remote URL in azure:// format. Paste into .dvc/config under url = <this value>."
  value       = "azure://${azurerm_storage_container.dvc_remote.name}"
}

# ---------------------------------------------------------------------------
# COMPUTE CLUSTERS
# ---------------------------------------------------------------------------

output "cpu_cluster_name" {
  description = "CPU compute cluster name. Reference in Azure ML job YAML as compute: azureml:<this value>."
  value       = azurerm_machine_learning_compute_cluster.cpu.name
}

output "gpu_training_cluster_name" {
  description = "GPU training compute cluster name. Reference in training job YAML and distributed training configs."
  value       = azurerm_machine_learning_compute_cluster.gpu_training.name
}

output "gpu_inference_cluster_name" {
  description = "GPU inference compute cluster name. Used for batch inference and pipeline inference steps."
  value       = azurerm_machine_learning_compute_cluster.gpu_inference.name
}

output "gpu_training_vm_size" {
  description = "VM size used by the GPU training cluster. Exposed for documentation and cost attribution."
  value       = azurerm_machine_learning_compute_cluster.gpu_training.vm_size
}

# ---------------------------------------------------------------------------
# ONLINE ENDPOINT
# ---------------------------------------------------------------------------

output "endpoint_name" {
  description = "Online endpoint resource name. Used by blue/green deployment scripts and traffic split updates."
  value       = azurerm_machine_learning_online_endpoint.serving.name
}

output "endpoint_scoring_uri" {
  description = "HTTPS scoring URI for the managed endpoint. POST JSON payloads here for real-time inference."
  value       = azurerm_machine_learning_online_endpoint.serving.scoring_uri
}

output "endpoint_swagger_uri" {
  description = "Swagger/OpenAPI spec URI for the managed endpoint. Useful for SDK clients and API gateway integration."
  value       = azurerm_machine_learning_online_endpoint.serving.swagger_uri
}

output "endpoint_principal_id" {
  description = "Object ID of the endpoint system-assigned managed identity. Grant additional RBAC roles here if the scoring container needs access to other Azure services."
  value       = azurerm_machine_learning_online_endpoint.serving.identity[0].principal_id
}

# ---------------------------------------------------------------------------
# CONTAINER REGISTRY
# ---------------------------------------------------------------------------

output "acr_login_server" {
  description = "ACR login server hostname (e.g. cracmlxyz123.azurecr.io). Used in Docker build/push commands and Kubernetes imagePullSecrets."
  value       = azurerm_container_registry.ml.login_server
}

output "acr_id" {
  description = "Container registry resource ID. Used for additional role assignments from platform modules."
  value       = azurerm_container_registry.ml.id
}

# ---------------------------------------------------------------------------
# KEY VAULT
# ---------------------------------------------------------------------------

output "key_vault_id" {
  description = "Key Vault resource ID. Grant Key Vault Secrets Officer role to engineers who need to write secrets."
  value       = azurerm_key_vault.ml.id
}

output "key_vault_uri" {
  description = "Key Vault vault URI (https://<name>.vault.azure.net/). Use in SDK v2 for secret store references."
  value       = azurerm_key_vault.ml.vault_uri
}

# ---------------------------------------------------------------------------
# OBSERVABILITY
# ---------------------------------------------------------------------------

output "application_insights_connection_string" {
  description = "Application Insights connection string. Set as APPLICATIONINSIGHTS_CONNECTION_STRING in serving containers. Mark as secret — contains instrumentation key."
  value       = azurerm_application_insights.ml.connection_string
  sensitive   = true
}

output "log_analytics_workspace_id" {
  description = "Log Analytics workspace resource ID. Used to configure diagnostic settings on additional resources."
  value       = azurerm_log_analytics_workspace.ml.id
}

# ---------------------------------------------------------------------------
# IDENTITY & SUBSCRIPTION
# ---------------------------------------------------------------------------

output "subscription_id" {
  description = "Azure subscription ID. Used by CI/CD scripts to scope az CLI commands."
  value       = data.azurerm_client_config.current.subscription_id
}

output "resource_group_name" {
  description = "Resource group name. Convenience alias for workspace_resource_group."
  value       = azurerm_resource_group.ml.name
}

# azure-ml/variables.tf
#
# All input variables for the Azure ML workspace module.
# Every variable has a description. Variables with restricted value sets
# have a validation block to fail fast with a clear error message.

# ---------------------------------------------------------------------------
# ENVIRONMENT & LOCATION
# ---------------------------------------------------------------------------

variable "environment" {
  type        = string
  description = "Deployment environment. Controls SKUs, replication, and purge protection."
  validation {
    condition     = contains(["dev", "staging", "production"], var.environment)
    error_message = "environment must be one of: dev, staging, production."
  }
}

variable "location" {
  type        = string
  description = "Primary Azure region for all resources. Run `az account list-locations -o table` for valid values."
  default     = "eastus"
}

variable "location_short" {
  type        = string
  description = "Short location code used in resource names (e.g. 'eus' for eastus, 'weu' for westeurope). Must be 2–5 lowercase characters."
  default     = "eus"
  validation {
    condition     = can(regex("^[a-z]{2,5}$", var.location_short))
    error_message = "location_short must be 2–5 lowercase letters, e.g. 'eus', 'weu', 'sea'."
  }
}

# ---------------------------------------------------------------------------
# WORKLOAD IDENTITY & COST ATTRIBUTION
# ---------------------------------------------------------------------------

variable "model_name" {
  type        = string
  description = "Logical model name. Used in resource names and cost tags. Must be lowercase-kebab-case (e.g. 'fraud-detection', 'churn-predictor')."
  validation {
    condition     = can(regex("^[a-z][a-z0-9-]+[a-z0-9]$", var.model_name))
    error_message = "model_name must be lowercase-kebab-case with no leading/trailing hyphens (e.g. 'fraud-detection')."
  }
}

variable "cost_center" {
  type        = string
  description = "Billing cost center code. Required for cost attribution — no default. Example: 'ml-platform', 'data-science-eu'."
}

variable "team" {
  type        = string
  description = "Owning team name. Applied as a tag to every resource for ownership tracking. Example: 'ml-platform-team'."
}

variable "additional_tags" {
  type        = map(string)
  description = "Additional resource tags to merge with the common tag set. Use for project-specific or compliance labels."
  default     = {}
}

# ---------------------------------------------------------------------------
# NETWORK ACCESS
# ---------------------------------------------------------------------------

variable "allow_public_network_access" {
  type        = bool
  description = "Allow public internet access to the workspace, storage, and endpoint. Set false in staging/production to force private endpoint traffic only."
  default     = true
}

variable "vnet_resource_group_name" {
  type        = string
  description = "Resource group of the VNet used for private endpoints. Required when allow_public_network_access = false. Platform team provides this value."
  default     = null
}

variable "vnet_name" {
  type        = string
  description = "Name of the VNet used for private endpoints. Required when allow_public_network_access = false."
  default     = null
}

variable "subnet_name" {
  type        = string
  description = "Name of the subnet within vnet_name for private endpoint NICs. Must have private endpoint network policies disabled."
  default     = null
}

# ---------------------------------------------------------------------------
# CPU COMPUTE CLUSTER
# ---------------------------------------------------------------------------

variable "cpu_cluster_vm_size" {
  type        = string
  description = "VM size for the CPU compute cluster. Used for preprocessing, evaluation, and registration steps. Example: 'Standard_DS3_v2', 'Standard_D4s_v5'."
  default     = "Standard_DS3_v2"
}

variable "cpu_cluster_max_nodes" {
  type        = number
  description = "Maximum node count for the CPU compute cluster. Scale-to-zero is always enabled (min = 0). Valid range: 1–100."
  default     = 4
  validation {
    condition     = var.cpu_cluster_max_nodes >= 1 && var.cpu_cluster_max_nodes <= 100
    error_message = "cpu_cluster_max_nodes must be between 1 and 100."
  }
}

# ---------------------------------------------------------------------------
# GPU TRAINING CLUSTER
#
# VM size reference (pass via var.gpu_cluster_vm_size):
#   Standard_NC6s_v3              1× V100 16GB       dev/experimentation
#   Standard_NC24ads_A100_v4      1× A100 80GB PCIe  single-GPU training/inference
#   Standard_NC40ads_H100_v5      1× H100 NVL 96GB   LLM inference
#   Standard_ND96asr_v4           8× A100 40GB SXM4  distributed training (quota req)
#   Standard_ND96isr_H100_v5      8× H100 80GB SXM5  distributed training (quota req)
#
# NDv4 and NDv5 require a support ticket quota increase (1–4 week wait).
# ---------------------------------------------------------------------------

variable "gpu_cluster_vm_size" {
  type        = string
  description = "VM size for the GPU training cluster. See variable comment for full size reference. A100/H100 NDv4/NDv5 require quota increase via support ticket."
  default     = "Standard_NC24ads_A100_v4"
}

variable "gpu_cluster_vm_priority" {
  type        = string
  description = "VM priority for the GPU training cluster. LowPriority (Spot) saves 60–80% over Dedicated; Azure may preempt with 30s notice. Use Dedicated in production."
  default     = "LowPriority"
  validation {
    condition     = contains(["LowPriority", "Dedicated"], var.gpu_cluster_vm_priority)
    error_message = "gpu_cluster_vm_priority must be 'LowPriority' or 'Dedicated'."
  }
}

variable "gpu_cluster_max_nodes" {
  type        = number
  description = "Maximum node count for the GPU training cluster. Valid range: 1–16. Values >4 typically require a quota increase. Contact platform team for NDv5 (H100) quotas."
  default     = 1
  validation {
    condition     = var.gpu_cluster_max_nodes >= 1 && var.gpu_cluster_max_nodes <= 16
    error_message = "gpu_cluster_max_nodes must be between 1 and 16. Values >4 may require a support-ticket quota increase."
  }
}

# ---------------------------------------------------------------------------
# GPU INFERENCE CLUSTER
# ---------------------------------------------------------------------------

variable "gpu_inference_vm_size" {
  type        = string
  description = "VM size for the GPU inference cluster. Uses Dedicated priority — never Spot for inference availability."
  default     = "Standard_NC24ads_A100_v4"
}

variable "gpu_inference_max_nodes" {
  type        = number
  description = "Maximum node count for the GPU inference cluster. Scale-to-zero is enabled; set higher for production steady-state latency."
  default     = 2
  validation {
    condition     = var.gpu_inference_max_nodes >= 1 && var.gpu_inference_max_nodes <= 16
    error_message = "gpu_inference_max_nodes must be between 1 and 16."
  }
}

# ---------------------------------------------------------------------------
# CONTAINER REGISTRY
# ---------------------------------------------------------------------------

variable "acr_georeplica_location" {
  type        = string
  description = "Azure region for ACR geo-replication. Requires Premium SKU (automatically selected in production). null disables geo-replication. Example: 'westeurope'."
  default     = null
}

# ---------------------------------------------------------------------------
# ENCRYPTION
# ---------------------------------------------------------------------------

variable "customer_managed_key_id" {
  type        = string
  description = "Azure Key Vault key ID for customer-managed encryption of workspace data at rest. null uses Microsoft-managed keys. Required for FedRAMP/HIPAA compliance. Mark as sensitive — do not log."
  default     = null
  sensitive   = true
}

# gcp-vertex-ai/main.tf
#
# Provisions GCP infrastructure for the ML platform:
#   - Cloud Storage bucket for MLflow artifacts.
#   - Vertex AI Feature Store.
#   - IAM binding so the MLflow service account can read/write artifacts.
#
# BEGINNER NOTE:
#   Terraform creates cloud resources declaratively — you describe WHAT you want
#   and Terraform figures out the API calls to make it happen.
#   Run `terraform plan` to preview changes before `terraform apply`.

terraform {
  required_version = ">= 1.6.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 5.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# ---------------------------------------------------------------------------
# GCS ARTIFACT BUCKET
# MLflow stores model binaries, plots, and evaluation reports here.
# ---------------------------------------------------------------------------
resource "google_storage_bucket" "ml_artifacts" {
  name                        = var.artifact_bucket_name
  location                    = var.region
  uniform_bucket_level_access = true

  # Prevent accidental deletion of the bucket containing all model artifacts.
  lifecycle {
    prevent_destroy = true
  }

  # Versioning allows recovery of accidentally overwritten artifacts.
  versioning {
    enabled = true
  }

  # Lifecycle rule: transition objects older than 90 days to Nearline storage
  # to reduce costs (Nearline is ~50% cheaper than Standard for infrequent access).
  lifecycle_rule {
    action {
      type          = "SetStorageClass"
      storage_class = "NEARLINE"
    }
    condition {
      age = 90
    }
  }
}

# ---------------------------------------------------------------------------
# IAM BINDING — MLflow Service Account → Artifact Bucket
# Grants the MLflow tracking server's service account permission to read
# and write objects in the artifact bucket.
#
# The service account email is passed in as a variable so this module can
# be used in multiple environments (dev, staging, production) without
# changing the resource definitions.
# ---------------------------------------------------------------------------
resource "google_storage_bucket_iam_member" "mlflow_artifact_access" {
  bucket = google_storage_bucket.ml_artifacts.name
  role   = "roles/storage.objectAdmin"
  member = "serviceAccount:${var.mlflow_service_account_email}"
}

# ---------------------------------------------------------------------------
# VERTEX AI FEATURE STORE
# Stores pre-computed features for training and online serving.
# See docs/guides/feature-store-patterns.md for usage patterns.
# ---------------------------------------------------------------------------
resource "google_vertex_ai_featurestore" "primary" {
  name   = var.featurestore_name
  region = var.region

  # Online serving config controls how many nodes back the online serving API.
  # Start with 1 node and increase based on QPS requirements.
  online_serving_config {
    fixed_node_count = 1
  }

  labels = {
    managed-by  = "terraform"
    environment = "production"
    team        = "ml-platform"
  }
}

# ---------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------
# Outputs are used by other Terraform modules and by application configuration.

output "artifact_bucket_name" {
  description = "Name of the GCS bucket used for MLflow artifact storage"
  value       = google_storage_bucket.ml_artifacts.name
}

output "artifact_bucket_url" {
  description = "gs:// URL for use as MLFLOW_DEFAULT_ARTIFACT_ROOT"
  value       = "gs://${google_storage_bucket.ml_artifacts.name}"
}

output "featurestore_id" {
  description = "Vertex AI Feature Store resource ID"
  value       = google_vertex_ai_featurestore.primary.id
}

variable "project_id" {
  type        = string
  description = "GCP project id"
}

variable "region" {
  type        = string
  description = "GCP region"
  default     = "us-central1"
}

variable "artifact_bucket_name" {
  type        = string
  description = "GCS bucket for artifacts"
}

variable "featurestore_name" {
  type        = string
  description = "Vertex AI Feature Store name"
  default     = "mlops-featurestore"
}

# Service account that the MLflow tracking server runs as.
# This account is granted roles/storage.objectAdmin on the artifact bucket.
# Format: <name>@<project>.iam.gserviceaccount.com
variable "mlflow_service_account_email" {
  type        = string
  description = "Email of the GCP service account used by the MLflow tracking server"
}

terraform {
  required_version = ">= 1.7.0"
  required_providers {
    github = {
      source  = "integrations/github"
      version = "~> 6.0"
    }
  }
}

provider "github" {
  owner = var.github_org
}

variable "github_org" {
  description = "GitHub organisation or user that owns the repository."
  type        = string
}

variable "github_repo" {
  description = "Repository name for the MLOps playbook."
  type        = string
  default     = "mlops-playbook"
}

# Register the GitHub App for the portal.
# The portal uses the installation token — never a PAT.
resource "github_app" "mlops_portal" {
  name        = "mlops-portal"
  description = "GitHub App for MLOps self-service portal workflow dispatches."
  url         = "https://github.com/${var.github_org}/${var.github_repo}"
}

output "app_id" {
  description = "GitHub App ID — store as GITHUB_APP_ID secret."
  value       = github_app.mlops_portal.app_id
  sensitive   = true
}

# terraform/ray-cluster/main.tf
# Terraform module: Ray cluster on Kubernetes (GPU node pool + KubeRay operator).
#
# PURPOSE:
#   Provisions:
#     - A GPU node pool in an existing Kubernetes cluster (EKS/GKE/AKS)
#     - KubeRay operator via Helm
#     - RBAC for KubeRay to manage RayJob / RayCluster CRDs
#
# USAGE:
#   terraform init
#   terraform apply -var-file=terraform.tfvars
#
# NOTE: This module assumes the cluster already exists and kubeconfig is
#       configured.  It does NOT create the cluster itself — use the
#       appropriate cluster module (aws-sagemaker, gcp-vertex-ai, etc.).

terraform {
  required_version = ">= 1.7.0"
  required_providers {
    helm = {
      source  = "hashicorp/helm"
      version = ">= 2.13.0"
    }
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = ">= 2.29.0"
    }
  }
}

# --------------------------------------------------------------------------- #
# Variables
# --------------------------------------------------------------------------- #

variable "namespace" {
  description = "Kubernetes namespace for the KubeRay operator."
  type        = string
  default     = "kuberay-operator"
}

variable "kuberay_version" {
  description = "KubeRay Helm chart version."
  type        = string
  default     = "1.1.1"
}

variable "ray_version" {
  description = "Ray version to use in RayCluster images."
  type        = string
  default     = "2.9.0"
}

variable "gpu_node_pool_enabled" {
  description = "Whether to create a dedicated GPU node pool."
  type        = bool
  default     = true
}

variable "gpu_instance_type" {
  description = "Cloud instance type for GPU nodes (e.g., g5.2xlarge on AWS)."
  type        = string
  default     = "g5.2xlarge"
}

variable "gpu_min_nodes" {
  description = "Minimum GPU node count."
  type        = number
  default     = 0
}

variable "gpu_max_nodes" {
  description = "Maximum GPU node count."
  type        = number
  default     = 8
}

variable "spot_enabled" {
  description = "Use spot/preemptible GPU nodes to reduce cost."
  type        = bool
  default     = true
}

variable "cost_center" {
  description = "Cost attribution label value."
  type        = string
  default     = "ml-platform"
}

variable "team" {
  description = "Team label for cost attribution."
  type        = string
  default     = "ml-platform"
}

# --------------------------------------------------------------------------- #
# KubeRay operator namespace
# --------------------------------------------------------------------------- #

resource "kubernetes_namespace" "kuberay" {
  metadata {
    name = var.namespace
    labels = {
      "app.kubernetes.io/managed-by" = "terraform"
      "cost-center"                  = var.cost_center
      "team"                         = var.team
    }
  }
}

# --------------------------------------------------------------------------- #
# KubeRay operator (Helm)
# --------------------------------------------------------------------------- #

resource "helm_release" "kuberay_operator" {
  name       = "kuberay-operator"
  repository = "https://ray-project.github.io/kuberay-helm/"
  chart      = "kuberay-operator"
  version    = var.kuberay_version
  namespace  = kubernetes_namespace.kuberay.metadata[0].name

  set {
    name  = "image.tag"
    value = "v${var.kuberay_version}"
  }

  set {
    name  = "batchScheduler.enabled"
    value = "true"
  }

  depends_on = [kubernetes_namespace.kuberay]
}

# --------------------------------------------------------------------------- #
# RBAC — allow KubeRay to manage RayJob/RayCluster in all namespaces
# --------------------------------------------------------------------------- #

resource "kubernetes_cluster_role" "kuberay_manager" {
  metadata {
    name = "kuberay-manager"
  }

  rule {
    api_groups = ["ray.io"]
    resources  = ["rayclusters", "rayjobs", "rayservices"]
    verbs      = ["get", "list", "watch", "create", "update", "patch", "delete"]
  }

  rule {
    api_groups = [""]
    resources  = ["pods", "services", "endpoints", "persistentvolumeclaims", "events"]
    verbs      = ["get", "list", "watch", "create", "update", "patch", "delete"]
  }

  rule {
    api_groups = ["batch"]
    resources  = ["jobs"]
    verbs      = ["get", "list", "watch", "create", "update", "patch", "delete"]
  }
}

resource "kubernetes_cluster_role_binding" "kuberay_manager" {
  metadata {
    name = "kuberay-manager"
  }

  role_ref {
    api_group = "rbac.authorization.k8s.io"
    kind      = "ClusterRole"
    name      = kubernetes_cluster_role.kuberay_manager.metadata[0].name
  }

  subject {
    kind      = "ServiceAccount"
    name      = "kuberay-operator"
    namespace = var.namespace
  }
}

# --------------------------------------------------------------------------- #
# Outputs
# --------------------------------------------------------------------------- #

output "kuberay_namespace" {
  description = "Namespace where KubeRay operator is deployed."
  value       = kubernetes_namespace.kuberay.metadata[0].name
}

output "kuberay_operator_release" {
  description = "Helm release name for the KubeRay operator."
  value       = helm_release.kuberay_operator.name
}

# terraform/ray-cluster/variables.tf
# Input variables for the Ray cluster Terraform module.
# Override defaults in terraform.tfvars or via -var CLI flags.

variable "kubeconfig_path" {
  description = "Path to kubeconfig file for the target cluster."
  type        = string
  default     = "~/.kube/config"
}

variable "kubeconfig_context" {
  description = "Kubeconfig context to use."
  type        = string
  default     = ""
}

variable "environment" {
  description = "Deployment environment (dev|staging|production)."
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "staging", "production"], var.environment)
    error_message = "environment must be one of: dev, staging, production."
  }
}

variable "tags" {
  description = "Additional resource tags applied to all cloud resources."
  type        = map(string)
  default     = {}
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 5.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# ──────────────────────────────────────────────────────────────────────────────
# Vertex AI Pipeline Storage Bucket
# ──────────────────────────────────────────────────────────────────────────────
resource "google_storage_bucket" "pipeline_artifacts" {
  name          = "${var.project_id}-vertex-pipeline-artifacts"
  location      = var.region
  force_destroy = false

  uniform_bucket_level_access = true

  versioning {
    enabled = true
  }

  lifecycle_rule {
    condition {
      age = 90
    }
    action {
      type = "Delete"
    }
  }

  labels = {
    cost-center  = var.cost_center
    team         = var.team
    environment  = var.environment
    managed-by   = "terraform"
  }
}

# ──────────────────────────────────────────────────────────────────────────────
# Service Account for Vertex Pipelines
# ──────────────────────────────────────────────────────────────────────────────
resource "google_service_account" "vertex_pipeline_sa" {
  account_id   = "vertex-pipeline-runner"
  display_name = "Vertex AI Pipeline Runner SA"
  project      = var.project_id
}

resource "google_project_iam_member" "vertex_pipeline_aiplatform" {
  project = var.project_id
  role    = "roles/aiplatform.user"
  member  = "serviceAccount:${google_service_account.vertex_pipeline_sa.email}"
}

resource "google_project_iam_member" "vertex_pipeline_storage" {
  project = var.project_id
  role    = "roles/storage.objectAdmin"
  member  = "serviceAccount:${google_service_account.vertex_pipeline_sa.email}"
}

resource "google_project_iam_member" "vertex_pipeline_artifact_registry" {
  project = var.project_id
  role    = "roles/artifactregistry.reader"
  member  = "serviceAccount:${google_service_account.vertex_pipeline_sa.email}"
}

# ──────────────────────────────────────────────────────────────────────────────
# Artifact Registry for pipeline component images
# ──────────────────────────────────────────────────────────────────────────────
resource "google_artifact_registry_repository" "pipeline_images" {
  location      = var.region
  repository_id = "mlops-pipeline-images"
  description   = "Container images for MLOps pipeline components"
  format        = "DOCKER"

  labels = {
    cost-center = var.cost_center
    team        = var.team
    environment = var.environment
  }
}

# ──────────────────────────────────────────────────────────────────────────────
# Vertex AI Metadata Store (tracks pipeline lineage)
# ──────────────────────────────────────────────────────────────────────────────
resource "google_vertex_ai_metadata_store" "default" {
  name        = "default"
  region      = var.region
  description = "MLOps pipeline metadata store"
  project     = var.project_id
}

# ──────────────────────────────────────────────────────────────────────────────
# Outputs
# ──────────────────────────────────────────────────────────────────────────────
output "pipeline_artifacts_bucket" {
  value = google_storage_bucket.pipeline_artifacts.name
}

output "vertex_pipeline_sa_email" {
  value = google_service_account.vertex_pipeline_sa.email
}

output "artifact_registry_hostname" {
  value = "${var.region}-docker.pkg.dev/${var.project_id}/${google_artifact_registry_repository.pipeline_images.repository_id}"
}

variable "project_id" {
  description = "GCP project ID"
  type        = string
}

variable "region" {
  description = "GCP region for Vertex AI resources"
  type        = string
  default     = "us-central1"
}

variable "environment" {
  description = "Deployment environment: dev | staging | production"
  type        = string
  default     = "staging"

  validation {
    condition     = contains(["dev", "staging", "production"], var.environment)
    error_message = "environment must be dev, staging, or production."
  }
}

variable "cost_center" {
  description = "Cost center label for billing attribution"
  type        = string
  default     = "ml-platform"
}

variable "team" {
  description = "Team label for billing attribution"
  type        = string
  default     = "mlops"
}

